input.old_string:
.pb-caption {
  font-size: 10px;
  color: var(--text-dim);
  font-weight: 500;
  white-space: nowrap;
}

input.new_string:
.pb-caption {
  font-size: 10px;
  color: var(--text-dim);
  font-weight: 500;
  white-space: nowrap;
}
.pb-caption-short { display: none; }

input.old_string:
@media (min-width: 721px) and (max-width: 820px) {
  .pb-caption { display: none; }
  .pb-btn { min-width: 36px; }
  .pb-btn--play { min-width: 44px; padding: 4px 6px; }
  .pb-input { width: 50px; font-size: 11px; }
  .speed-preset { padding: 2px 4px !important; min-width: 26px; font-size: 10px; }
  #playbackBar { gap: 2px; padding: 5px 8px; }
}

input.new_string:
@media (min-width: 721px) and (max-width: 820px) {
  /* Keep short Step / Seg / Cand labels so three identical ← 0/0 → groups
     stay distinguishable without the wider full captions. */
  .pb-caption-long { display: none; }
  .pb-caption-short { display: inline; }
  .pb-caption { font-size: 9px; }
  .pb-btn { min-width: 36px; }
  .pb-btn--play { min-width: 44px; padding: 4px 6px; }
  .pb-input { width: 50px; font-size: 11px; }
  .speed-preset { padding: 2px 4px !important; min-width: 26px; font-size: 10px; }
  #playbackBar { gap: 2px; padding: 5px 8px; }
}
